// Convertible web app - service worker.
//
// Precaches the complete app (shell, modules, WebAssembly core, fonts,
// icons) into a cache named after a digest of every file, serves it
// cache-first so the app works fully offline after the first visit, and
// receives files shared to the installed app (Web Share Target).
//
// A new version installs in the background and waits; the page offers
// "New version available - Reload", which sends {type:'skip-waiting'}.
//
// The list below is generated by tools/assemble.mjs.
// Copyright (c) Convertible contributors. MIT licence; see LICENSE.

/* precache:start */
const CACHE_VERSION = 'dev';
const PRECACHE = [];
/* precache:end */

const CACHE_PREFIX = 'convertible-app-';
const CACHE_NAME = `${CACHE_PREFIX}${CACHE_VERSION}`;
const SHARE_INBOX = 'convertible-share-inbox';

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE_NAME);
      // Bypass the HTTP cache so a new version never mixes in stale files.
      await cache.addAll(PRECACHE.map((url) => new Request(url, { cache: 'reload' })));
    })(),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(names.filter((n) => n.startsWith(CACHE_PREFIX) && n !== CACHE_NAME).map((n) => caches.delete(n)));
      await self.clients.claim();
    })(),
  );
});

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'skip-waiting') self.skipWaiting();
  if (event.data && event.data.type === 'version' && event.ports[0]) event.ports[0].postMessage(CACHE_VERSION);
});

const scopeUrl = new URL(self.registration.scope);

async function fromCache(request) {
  const cache = await caches.open(CACHE_NAME);
  const hit = await cache.match(request, { ignoreSearch: true });
  if (hit) return hit;
  try {
    return await fetch(request);
  } catch {
    return new Response('Offline and not cached.', { status: 504, headers: { 'Content-Type': 'text/plain' } });
  }
}

async function appShell() {
  const cache = await caches.open(CACHE_NAME);
  const hit = await cache.match('./index.html');
  if (hit) return hit;
  return fetch(new URL('./index.html', scopeUrl));
}

/** Web Share Target: keep the shared files just long enough for the page to take them. */
async function receiveShare(request) {
  try {
    const form = await request.formData();
    const inbox = await caches.open(SHARE_INBOX);
    let n = 0;
    for (const value of form.getAll('files')) {
      if (!(value instanceof File)) continue;
      n += 1;
      const headers = new Headers({
        'Content-Type': value.type || 'application/octet-stream',
        'X-File-Name': encodeURIComponent(value.name || `shared-${n}`),
      });
      await inbox.put(new Request(new URL(`./__share/${Date.now()}-${n}`, scopeUrl)), new Response(value, { headers }));
    }
    const text = [form.get('title'), form.get('text')].filter((v) => typeof v === 'string' && v.trim()).join('\n');
    if (!n && text) {
      const headers = new Headers({ 'Content-Type': 'text/plain;charset=utf-8', 'X-File-Name': encodeURIComponent('Shared text.txt') });
      await inbox.put(new Request(new URL(`./__share/${Date.now()}-text`, scopeUrl)), new Response(text, { headers }));
    }
  } catch {
    /* fall through to the app; it shows an empty queue */
  }
  return Response.redirect(new URL('./?share=1', scopeUrl).href, 303);
}

self.addEventListener('fetch', (event) => {
  const request = event.request;
  const url = new URL(request.url);
  if (url.origin !== scopeUrl.origin) return; // the app never makes cross-origin requests
  if (request.method === 'POST' && url.pathname === new URL('./share-target', scopeUrl).pathname) {
    event.respondWith(receiveShare(request));
    return;
  }
  if (request.method !== 'GET') return;
  if (request.mode === 'navigate') {
    event.respondWith(appShell());
    return;
  }
  event.respondWith(fromCache(request));
});
